// Gerado por scripts/build-workflows.js a partir de src/. Edite o módulo, não este nó.
// ---- src/validators.js ----
// Validadores estritos para todo valor que vem do texto de um card.
// Regra geral: se não passar aqui, não vira argumento de comando.

const CPANEL_USER_RE = /^[a-z][a-z0-9]{0,15}$/;
const RESERVED_SYSTEM_USERS = new Set([
  'root', 'admin', 'nobody', 'cpanel', 'cpanelphpmyadmin', 'cpses', 'mail', 'mailman',
  'mysql', 'named', 'system', 'daemon', 'bin', 'sys', 'sshd', 'ftp', 'apache', 'www',
]);

function isValidCpanelUser(value) {
  return typeof value === 'string' && CPANEL_USER_RE.test(value) && !RESERVED_SYSTEM_USERS.has(value);
}

const ISSUE_KEY_RE = /^[A-Z][A-Z0-9_]{1,9}-[1-9][0-9]{0,6}$/;

function isValidIssueKey(value) {
  return typeof value === 'string' && ISSUE_KEY_RE.test(value);
}

// ---------------------------------------------------------------------------
// Hostnames
// ---------------------------------------------------------------------------
const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

function isValidHostname(value) {
  if (typeof value !== 'string' || value.length === 0 || value.length > 253) return false;
  if (value !== value.toLowerCase()) return false;
  const labels = value.split('.');
  if (labels.length < 2) return false;
  if (!labels.every((l) => LABEL_RE.test(l))) return false;
  const tld = labels[labels.length - 1];
  return /^[a-z]{2,63}$/.test(tld) || /^xn--[a-z0-9-]{1,59}$/.test(tld);
}

// ---------------------------------------------------------------------------
// E-mail (RFC simplificado, só o que uma caixa cPanel aceita na prática)
// ---------------------------------------------------------------------------
const MAIL_LOCAL_RE = /^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$/;

function parseEmail(value) {
  if (typeof value !== 'string') return null;
  const v = value.trim().toLowerCase();
  if (v.length > 254) return null;
  const parts = v.split('@');
  if (parts.length !== 2) return null;
  const [local, domain] = parts;
  if (!MAIL_LOCAL_RE.test(local) || local.includes('..')) return null;
  if (!isValidHostname(domain)) return null;
  return { local, domain, address: local + '@' + domain };
}

// ---------------------------------------------------------------------------
// IPv4
// ---------------------------------------------------------------------------
function parseIPv4(value) {
  if (typeof value !== 'string') return null;
  const parts = value.split('.');
  if (parts.length !== 4) return null;
  const octets = [];
  for (const p of parts) {
    // sem zeros à esquerda (evita ambiguidade octal) e só dígitos
    if (!/^(?:0|[1-9][0-9]{0,2})$/.test(p)) return null;
    const n = Number(p);
    if (n > 255) return null;
    octets.push(n);
  }
  return octets;
}

// Faixas especiais (RFC 6890 e correlatas) escritas como octetos para manter
// o repositório livre de endereços em notação pontuada fora das faixas de documentação.
const IPV4_SPECIAL = [
  { base: [0, 0, 0, 0], bits: 8 },        // "this network"
  { base: [10, 0, 0, 0], bits: 8 },       // RFC 1918
  { base: [100, 64, 0, 0], bits: 10 },    // CGNAT
  { base: [127, 0, 0, 0], bits: 8 },      // loopback
  { base: [169, 254, 0, 0], bits: 16 },   // link-local
  { base: [172, 16, 0, 0], bits: 12 },    // RFC 1918
  { base: [192, 0, 0, 0], bits: 24 },     // IETF protocol assignments
  { base: [192, 0, 2, 0], bits: 24 },     // TEST-NET-1
  { base: [192, 88, 99, 0], bits: 24 },   // 6to4 relay anycast
  { base: [192, 168, 0, 0], bits: 16 },   // RFC 1918
  { base: [198, 18, 0, 0], bits: 15 },    // benchmarking
  { base: [198, 51, 100, 0], bits: 24 },  // TEST-NET-2
  { base: [203, 0, 113, 0], bits: 24 },   // TEST-NET-3
  { base: [224, 0, 0, 0], bits: 4 },      // multicast
  { base: [240, 0, 0, 0], bits: 4 },      // reservado + broadcast
];

function ipv4ToInt(o) {
  return ((o[0] << 24) >>> 0) + (o[1] << 16) + (o[2] << 8) + o[3];
}

function ipv4InRange(octets, range) {
  const mask = range.bits === 0 ? 0 : (0xffffffff << (32 - range.bits)) >>> 0;
  return ((ipv4ToInt(octets) & mask) >>> 0) === ((ipv4ToInt(range.base) & mask) >>> 0);
}

function isPublicIPv4(value) {
  const o = parseIPv4(value);
  if (!o) return false;
  return !IPV4_SPECIAL.some((r) => ipv4InRange(o, r));
}

// ---------------------------------------------------------------------------
// IPv6
// ---------------------------------------------------------------------------
function parseIPv6(value) {
  if (typeof value !== 'string' || value.length > 45) return null;
  let v = value.trim().toLowerCase();
  if (v.includes('%')) return null; // zone id não é aceito
  const lastColon = v.lastIndexOf(':');
  if (lastColon !== -1 && v.slice(lastColon + 1).includes('.')) {
    // IPv4 embutido no fim (ex.: ::ffff:a.b.c.d) vira dois grupos hexadecimais
    const v4 = parseIPv4(v.slice(lastColon + 1));
    if (!v4) return null;
    const hi = ((v4[0] << 8) | v4[1]).toString(16);
    const lo = ((v4[2] << 8) | v4[3]).toString(16);
    v = v.slice(0, lastColon + 1) + hi + ':' + lo;
  }
  const doubleColon = v.split('::');
  if (doubleColon.length > 2) return null;
  const toGroups = (s) => (s === '' ? [] : s.split(':'));
  const head = toGroups(doubleColon[0]);
  const rest = doubleColon.length === 2 ? toGroups(doubleColon[1]) : [];
  const hexOk = (g) => /^[0-9a-f]{1,4}$/.test(g);
  if (!head.every(hexOk) || !rest.every(hexOk)) return null;
  const explicit = head.length + rest.length;
  let groups;
  if (doubleColon.length === 2) {
    if (explicit > 7) return null;
    groups = [...head, ...Array(8 - explicit).fill('0'), ...rest].map((g) => parseInt(g, 16));
  } else {
    if (explicit !== 8) return null;
    groups = [...head, ...rest].map((g) => parseInt(g, 16));
  }
  return groups.length === 8 ? groups : null;
}

function formatIPv6(groups) {
  // RFC 5952: minúsculas, sem zeros à esquerda, comprime a maior sequência (>=2) de zeros
  let bestStart = -1;
  let bestLen = 0;
  for (let i = 0; i < 8; ) {
    if (groups[i] !== 0) { i++; continue; }
    let j = i;
    while (j < 8 && groups[j] === 0) j++;
    if (j - i > bestLen && j - i >= 2) { bestStart = i; bestLen = j - i; }
    i = j;
  }
  const hex = groups.map((g) => g.toString(16));
  if (bestStart === -1) return hex.join(':');
  const left = hex.slice(0, bestStart).join(':');
  const right = hex.slice(bestStart + bestLen).join(':');
  return left + '::' + right;
}

const IPV6_SPECIAL = [
  ['2001::', 23],      // IETF protocol assignments (inclui Teredo)
  ['2001:db8::', 32],  // documentação
  ['2002::', 16],      // 6to4
].map(([p, bits]) => ({ groups: parseIPv6(p), bits }));

function ipv6InPrefix(groups, prefix) {
  let bits = prefix.bits;
  for (let i = 0; i < 8 && bits > 0; i++) {
    const take = Math.min(16, bits);
    const mask = (0xffff << (16 - take)) & 0xffff;
    if ((groups[i] & mask) !== (prefix.groups[i] & mask)) return false;
    bits -= take;
  }
  return true;
}

function isPublicIPv6(value) {
  const g = parseIPv6(value);
  if (!g) return false;
  // somente unicast global (2000::/3), menos as faixas especiais acima
  if ((g[0] & 0xe000) !== 0x2000) return false;
  return !IPV6_SPECIAL.some((p) => ipv6InPrefix(g, p));
}

/**
 * Normaliza e valida um IP para desbloqueio. Retorna a forma canônica ou null.
 * Só aceita endereços públicos: desbloquear faixa privada/reservada não faz
 * sentido operacional e costuma ser sinal de erro ou abuso.
 */
function normalizePublicIp(value) {
  if (typeof value !== 'string') return null;
  const v = value.trim();
  if (v.includes(':')) {
    const g = parseIPv6(v);
    if (!g || !isPublicIPv6(v)) return null;
    return { version: 6, address: formatIPv6(g) };
  }
  if (!isPublicIPv4(v)) return null;
  return { version: 4, address: v };
}

// ---- src/text.js ----
// Extração de texto do card (Atlassian Document Format) e leitura de campos
// estruturados no formato "Chave: valor", um por linha.

const MAX_TEXT_LENGTH = 20000;

function adfToText(node) {
  if (node == null) return '';
  if (typeof node === 'string') return node.slice(0, MAX_TEXT_LENGTH);
  const out = [];
  const walk = (n) => {
    if (!n || typeof n !== 'object') return;
    if (n.type === 'text' && typeof n.text === 'string') out.push(n.text);
    if (n.type === 'hardBreak') out.push('\n');
    if (Array.isArray(n.content)) n.content.forEach(walk);
    if (['paragraph', 'heading', 'listItem', 'codeBlock', 'blockquote'].includes(n.type)) out.push('\n');
  };
  walk(node);
  return out.join('').replace(/\n{3,}/g, '\n\n').trim().slice(0, MAX_TEXT_LENGTH);
}

function normalizeKey(value) {
  return String(value)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

// Nome canônico do campo -> variações aceitas no template do card
const FIELD_ALIASES = {
  cliente: ['cliente', 'contacpanel', 'usuariocpanel', 'usuario'],
  ip: ['ip', 'enderecoip', 'ipbloqueado'],
  email: ['email', 'contadeemail', 'caixapostal', 'conta'],
  atividade: ['atividade', 'tipo', 'tipodeatividade'],
  periodo: ['periodo'],
};

const ALIAS_TO_FIELD = Object.entries(FIELD_ALIASES).reduce((acc, [field, aliases]) => {
  aliases.forEach((a) => { acc[a] = field; });
  return acc;
}, {});

/**
 * Lê linhas "Chave: valor". Só campos conhecidos são considerados; um campo
 * repetido com valores diferentes é marcado como ambíguo (o card é recusado).
 */
function parseFields(text) {
  const fields = {};
  const ambiguous = new Set();
  String(text || '').split(/\r?\n/).forEach((line) => {
    const m = line.match(/^\s*[-*]?\s*([^:]{1,40}):\s*(.{1,320}?)\s*$/);
    if (!m) return;
    const field = ALIAS_TO_FIELD[normalizeKey(m[1])];
    if (!field) return;
    const value = m[2].trim();
    if (fields[field] !== undefined && fields[field] !== value) ambiguous.add(field);
    else fields[field] = value;
  });
  return { fields, ambiguous: [...ambiguous] };
}

function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

// ---- src/inventory.js ----
// Inventório: fonte da verdade sobre quais contas existem, em qual servidor
// estão, quais domínios pertencem a cada conta e quem é o contato responsável.
// O texto do card nunca decide servidor nem dono de domínio: só o inventário.



const SERVER_NAME_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;

function parseInventory(raw) {
  let inv = raw;
  if (typeof raw === 'string') {
    try { inv = JSON.parse(raw); } catch (e) { throw new Error('inventory: JSON inválido'); }
  }
  if (!inv || typeof inv !== 'object') throw new Error('inventory: objeto ausente');
  const servers = inv.servers || {};
  const accounts = inv.accounts || {};
  for (const [name, srv] of Object.entries(servers)) {
    if (!SERVER_NAME_RE.test(name)) throw new Error('inventory: nome de servidor inválido');
    if (!srv || !isValidHostname(srv.host)) throw new Error('inventory: host inválido em ' + name);
  }
  const aliasIndex = new Map();
  for (const [user, acc] of Object.entries(accounts)) {
    if (!isValidCpanelUser(user)) throw new Error('inventory: usuário cPanel inválido');
    if (!acc || !servers[acc.server]) throw new Error('inventory: servidor desconhecido para ' + user);
    if (!Array.isArray(acc.domains) || !acc.domains.every(isValidHostname)) {
      throw new Error('inventory: domínios inválidos para ' + user);
    }
    if (acc.contact !== undefined && !parseEmail(acc.contact)) {
      throw new Error('inventory: contato inválido para ' + user);
    }
    for (const alias of [user, ...(acc.aliases || [])]) {
      const k = normalizeKey(alias);
      if (!k) continue;
      if (!aliasIndex.has(k)) aliasIndex.set(k, new Set());
      aliasIndex.get(k).add(user);
    }
  }
  return { servers, accounts, aliasIndex };
}

/**
 * Resolve o campo "Cliente" do card para uma conta do inventário.
 * Correspondência exata (usuário ou alias normalizado). Sem busca por
 * substring: "ana" nunca deve casar com "mariana".
 */
function resolveAccount(inventory, value) {
  const k = normalizeKey(value || '');
  if (!k) return { status: 'missing' };
  const users = inventory.aliasIndex.get(k);
  if (!users || users.size === 0) return { status: 'not_found' };
  if (users.size > 1) return { status: 'ambiguous' };
  const user = [...users][0];
  const account = inventory.accounts[user];
  return { status: 'ok', user, account, server: account.server, host: inventory.servers[account.server].host };
}

function accountOwnsDomain(account, domain) {
  return Array.isArray(account.domains) && account.domains.includes(domain);
}

/** Domínio (ou subdomínio) -> conta dona, pelo sufixo mais longo em fronteira de rótulo. */
function findAccountByHostname(inventory, hostname) {
  let best = null;
  for (const [user, acc] of Object.entries(inventory.accounts)) {
    for (const d of acc.domains) {
      if (hostname === d || hostname.endsWith('.' + d)) {
        if (!best || d.length > best.domain.length) best = { user, domain: d, server: acc.server };
      }
    }
  }
  if (!best) return null;
  return { ...best, host: inventory.servers[best.server].host };
}

// ---- src/config.js ----
// Configuração lida de variáveis de ambiente do n8n ($env).
// Só configuração vai aqui; segredos ficam no cofre de credenciais do n8n.
// Padrões seguros: dry-run ligado, allowlist vazia, aprovação obrigatória.


function parseBool(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  return /^(1|true|yes|sim|on)$/i.test(String(value).trim());
}

function parseIntInRange(value, fallback, min, max) {
  const n = Number.parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function parseList(value) {
  return String(value || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

const SSH_MODES = ['forced-command', 'sudo-wrapper'];

function readConfig(env) {
  const e = env || {};
  const sshMode = SSH_MODES.includes(e.OPS_SSH_MODE) ? e.OPS_SSH_MODE : 'forced-command';
  return {
    jiraBaseUrl: String(e.JIRA_BASE_URL || 'https://example.atlassian.net').replace(/\/+$/, ''),
    projectKeys: parseList(e.JIRA_PROJECT_KEYS || 'OPS'),
    automationStatus: e.JIRA_AUTOMATION_STATUS || 'Selecionado para Automação',
    statusDone: e.JIRA_STATUS_DONE || 'Conferir e Avisar',
    statusTriage: e.JIRA_STATUS_TRIAGE || 'Triagem Manual',
    claimLabel: e.JIRA_CLAIM_LABEL || 'ops-automation-claimed',
    botAccountId: e.JIRA_BOT_ACCOUNT_ID || '',
    approverIds: parseList(e.OPS_APPROVER_ACCOUNT_IDS),
    requireFourEyes: parseBool(e.OPS_REQUIRE_FOUR_EYES, true),
    dryRun: parseBool(e.OPS_DRY_RUN, true),
    allowedActivities: parseList(e.OPS_ALLOWED_ACTIVITIES),
    maxActionsPerRun: parseIntInRange(e.OPS_MAX_ACTIONS_PER_RUN, 5, 0, 50),
    searchMaxResults: parseIntInRange(e.JIRA_SEARCH_MAX_RESULTS, 25, 1, 100),
    sshMode,
    passwordLength: parseIntInRange(e.OPS_PASSWORD_LENGTH, 20, 16, 64),
    secretTtlHours: parseIntInRange(e.OPS_SECRET_TTL_HOURS, 24, 1, 72),
    sslMaxRetries: parseIntInRange(e.SSL_MAX_RETRIES, 1, 0, 3),
    sslDedupHours: parseIntInRange(e.SSL_DEDUP_HOURS, 12, 0, 168),
    inventory: parseInventory(e.OPS_INVENTORY_JSON || '{"servers":{},"accounts":{}}'),
  };
}

// ---- src/catalog.js ----
// Catálogo fixo de operações. A automação nunca monta shell livre: ela
// escolhe uma entrada daqui e passa argumentos já validados. No servidor,
// o wrapper server/ops-catalog.sh valida tudo de novo (defesa em profundidade).

const CATALOG = Object.freeze({
  ip_unblock: Object.freeze({
    executor: 'ssh',
    command: 'ip-unblock',
    label: 'Desbloqueio de IP no firewall',
  }),
  mail_quota_increase: Object.freeze({
    executor: 'ssh',
    command: 'mail-quota-increase',
    label: 'Aumento de cota de e-mail',
  }),
  mail_password_reset: Object.freeze({
    executor: 'whm',
    label: 'Redefinição de senha de e-mail',
    deliversSecret: true,
  }),
  usage_report: Object.freeze({
    executor: 'manual',
    label: 'Relatório de usabilidade',
  }),
});

// Comandos internos (não acionáveis por card), usados por outros workflows
const INTERNAL_COMMANDS = Object.freeze(['ssl-autossl']);

const SAFE_ARG_RE = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,252}$/;
const WRAPPER_PATH = '/usr/local/sbin/ops-catalog';

/** Quoting POSIX: tudo entre aspas simples; aspas simples internas viram '\'' */
function shQuote(value) {
  return "'" + String(value).replace(/'/g, "'\\''") + "'";
}

function knownCommand(commandId) {
  return INTERNAL_COMMANDS.includes(commandId) ||
    Object.values(CATALOG).some((e) => e.command === commandId);
}

/**
 * Monta a linha enviada pelo nó SSH.
 * - forced-command: a chave SSH do bot só executa o wrapper (authorized_keys
 *   command=...), que recebe a linha em SSH_ORIGINAL_COMMAND. Os argumentos
 *   precisam ser de um charset seguro, sem espaço nem aspas.
 * - sudo-wrapper: chama o wrapper via sudo, com cada argumento entre aspas.
 * Nos dois modos, argumento fora do charset seguro é recusado antes de sair do n8n.
 */
function buildCatalogCommand(commandId, args, mode) {
  if (!knownCommand(commandId)) throw new Error('catalog: comando desconhecido');
  if (!Array.isArray(args)) throw new Error('catalog: argumentos inválidos');
  for (const a of args) {
    if (typeof a !== 'string' || !SAFE_ARG_RE.test(a)) throw new Error('catalog: argumento fora do charset seguro');
  }
  const argv = [commandId, ...args];
  if (mode === 'forced-command') return argv.join(' ');
  if (mode === 'sudo-wrapper') return ['sudo', '-n', WRAPPER_PATH, ...argv.map(shQuote)].join(' ');
  throw new Error('catalog: modo SSH desconhecido');
}

// ---- src/ssl.js ----
// Renovação de SSL via AutoSSL disparada por alerta de vencimento do Uptime Kuma.




function extractKumaDomain(body) {
  const monitor = (body && body.monitor) || {};
  let host = typeof monitor.hostname === 'string' ? monitor.hostname : '';
  if (!host && typeof monitor.url === 'string') {
    try { host = new URL(monitor.url).hostname; } catch (e) { host = ''; }
  }
  host = host.trim().toLowerCase().replace(/\.$/, '').replace(/^www\./, '');
  return isValidHostname(host) ? host : null;
}

function isCertExpiryEvent(body) {
  const msg = String((body && body.msg) || '').toLowerCase();
  return /(certificate|certificado)/.test(msg) && /expir/.test(msg);
}

/**
 * Decide se um alerta vira execução.
 * state.seen guarda domínio -> timestamp do último disparo (deduplicação).
 */
function prepareSslJob(body, cfg, state) {
  if (!isCertExpiryEvent(body)) return { status: 'ignore', reason: 'not_cert_expiry_event' };
  const domain = extractKumaDomain(body);
  if (!domain) return { status: 'reject', reason: 'invalid_domain' };
  const owner = findAccountByHostname(cfg.inventory, domain);
  if (!owner) return { status: 'reject', reason: 'domain_not_in_inventory', domain };

  const now = state.now;
  const windowMs = cfg.sslDedupHours * 3600 * 1000;
  const seen = state.seen || {};
  for (const [d, ts] of Object.entries(seen)) if (now - ts > windowMs) delete seen[d];
  if (seen[domain] && now - seen[domain] <= windowMs) return { status: 'ignore', reason: 'duplicate_within_window', domain };
  seen[domain] = now;

  return {
    status: 'run',
    job: {
      domain,
      cpanelUser: owner.user,
      server: owner.server,
      host: owner.host,
      sshCommand: buildCatalogCommand('ssl-autossl', [owner.user, domain], cfg.sshMode),
    },
  };
}

function problemMatchesDomain(problemDomain, domain) {
  const d = String(problemDomain || '').toLowerCase().replace(/^\*\./, '');
  return d === domain || d.endsWith('.' + domain);
}

/**
 * success      -> sem problemas para o domínio
 * dns_manual   -> validação DNS (ex.: wildcard): retry não resolve
 * other_failure-> HTTP DCV, conectividade, erro do wrapper: vale 1 retry
 */
function classifyAutoSsl(parsed, domain, attempt, maxRetries) {
  if (!parsed || !parsed.ok) {
    const status = 'other_failure';
    return { status, problems: [], error: (parsed && parsed.error) || 'unknown_error', attempt, retry: attempt <= maxRetries };
  }
  const all = Array.isArray(parsed.data && parsed.data.problems) ? parsed.data.problems : [];
  const problems = all
    .filter((p) => p && problemMatchesDomain(p.domain, domain))
    .slice(0, 20)
    .map((p) => ({ domain: String(p.domain).slice(0, 253), problem: String(p.problem || '').slice(0, 300) }));
  let status = 'success';
  if (problems.length) status = problems.some((p) => /\bdns\b/i.test(p.problem)) ? 'dns_manual' : 'other_failure';
  return { status, problems, error: null, attempt, retry: status === 'other_failure' && attempt <= maxRetries };
}

const TEAMS_STYLE = {
  success: { title: 'Certificado renovado', color: 'Good' },
  dns_manual: { title: 'Ação manual necessária (validação DNS)', color: 'Warning' },
  other_failure: { title: 'Falha na renovação do certificado', color: 'Attention' },
  rejected: { title: 'Alerta de certificado não processado', color: 'Warning' },
};

/** Payload de Adaptive Card para webhook do Teams (Workflows). Montado como objeto: sem JSON por concatenação. */
function buildTeamsMessage(result) {
  const style = TEAMS_STYLE[result.status] || TEAMS_STYLE.other_failure;
  const facts = [
    { title: 'Domínio', value: result.domain || 'n/d' },
    { title: 'Servidor', value: result.server || 'n/d' },
    { title: 'Tentativas', value: String(result.attempt || 0) },
  ];
  if (result.reason) facts.push({ title: 'Motivo', value: result.reason });
  if (result.error) facts.push({ title: 'Erro', value: result.error });
  const body = [
    { type: 'TextBlock', size: 'Medium', weight: 'Bolder', color: style.color, text: style.title, wrap: true },
    { type: 'FactSet', facts },
  ];
  (result.problems || []).slice(0, 10).forEach((p) => {
    body.push({ type: 'TextBlock', wrap: true, isSubtle: true, text: p.domain + ': ' + p.problem });
  });
  if (result.status === 'dns_manual') {
    body.push({ type: 'TextBlock', wrap: true, text: 'Configure o registro TXT de validação ou remova o wildcard do escopo do AutoSSL.' });
  }
  return {
    type: 'message',
    attachments: [{
      contentType: 'application/vnd.microsoft.card.adaptive',
      content: { type: 'AdaptiveCard', version: '1.4', body },
    }],
  };
}

// ---- cola do nó ----
const cfg = readConfig($env);
const body = $input.first().json.body || {};
const store = $getWorkflowStaticData('global');
store.sslSeen = store.sslSeen || {};
const r = prepareSslJob(body, cfg, { now: Date.now(), seen: store.sslSeen });
if (r.status === 'run') return [{ json: { route: 'run', ...r.job } }];
return [{ json: { route: r.status, status: 'rejected', reason: r.reason, domain: r.domain || null, attempt: 0 } }];

// Gerado por scripts/build-workflows.js a partir de src/. Edite o módulo, não este nó.
// ---- src/validators.js ----
// Validadores estritos para todo valor que vem do texto de um card.
// Regra geral: se não passar aqui, não vira argumento de comando.

const CPANEL_USER_RE = /^[a-z][a-z0-9]{0,15}$/;
const RESERVED_SYSTEM_USERS = new Set([
  'root', 'admin', 'nobody', 'cpanel', 'cpanelphpmyadmin', 'cpses', 'mail', 'mailman',
  'mysql', 'named', 'system', 'daemon', 'bin', 'sys', 'sshd', 'ftp', 'apache', 'www',
]);

function isValidCpanelUser(value) {
  return typeof value === 'string' && CPANEL_USER_RE.test(value) && !RESERVED_SYSTEM_USERS.has(value);
}

const ISSUE_KEY_RE = /^[A-Z][A-Z0-9_]{1,9}-[1-9][0-9]{0,6}$/;

function isValidIssueKey(value) {
  return typeof value === 'string' && ISSUE_KEY_RE.test(value);
}

// ---------------------------------------------------------------------------
// Hostnames
// ---------------------------------------------------------------------------
const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

function isValidHostname(value) {
  if (typeof value !== 'string' || value.length === 0 || value.length > 253) return false;
  if (value !== value.toLowerCase()) return false;
  const labels = value.split('.');
  if (labels.length < 2) return false;
  if (!labels.every((l) => LABEL_RE.test(l))) return false;
  const tld = labels[labels.length - 1];
  return /^[a-z]{2,63}$/.test(tld) || /^xn--[a-z0-9-]{1,59}$/.test(tld);
}

// ---------------------------------------------------------------------------
// E-mail (RFC simplificado, só o que uma caixa cPanel aceita na prática)
// ---------------------------------------------------------------------------
const MAIL_LOCAL_RE = /^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$/;

function parseEmail(value) {
  if (typeof value !== 'string') return null;
  const v = value.trim().toLowerCase();
  if (v.length > 254) return null;
  const parts = v.split('@');
  if (parts.length !== 2) return null;
  const [local, domain] = parts;
  if (!MAIL_LOCAL_RE.test(local) || local.includes('..')) return null;
  if (!isValidHostname(domain)) return null;
  return { local, domain, address: local + '@' + domain };
}

// ---------------------------------------------------------------------------
// IPv4
// ---------------------------------------------------------------------------
function parseIPv4(value) {
  if (typeof value !== 'string') return null;
  const parts = value.split('.');
  if (parts.length !== 4) return null;
  const octets = [];
  for (const p of parts) {
    // sem zeros à esquerda (evita ambiguidade octal) e só dígitos
    if (!/^(?:0|[1-9][0-9]{0,2})$/.test(p)) return null;
    const n = Number(p);
    if (n > 255) return null;
    octets.push(n);
  }
  return octets;
}

// Faixas especiais (RFC 6890 e correlatas) escritas como octetos para manter
// o repositório livre de endereços em notação pontuada fora das faixas de documentação.
const IPV4_SPECIAL = [
  { base: [0, 0, 0, 0], bits: 8 },        // "this network"
  { base: [10, 0, 0, 0], bits: 8 },       // RFC 1918
  { base: [100, 64, 0, 0], bits: 10 },    // CGNAT
  { base: [127, 0, 0, 0], bits: 8 },      // loopback
  { base: [169, 254, 0, 0], bits: 16 },   // link-local
  { base: [172, 16, 0, 0], bits: 12 },    // RFC 1918
  { base: [192, 0, 0, 0], bits: 24 },     // IETF protocol assignments
  { base: [192, 0, 2, 0], bits: 24 },     // TEST-NET-1
  { base: [192, 88, 99, 0], bits: 24 },   // 6to4 relay anycast
  { base: [192, 168, 0, 0], bits: 16 },   // RFC 1918
  { base: [198, 18, 0, 0], bits: 15 },    // benchmarking
  { base: [198, 51, 100, 0], bits: 24 },  // TEST-NET-2
  { base: [203, 0, 113, 0], bits: 24 },   // TEST-NET-3
  { base: [224, 0, 0, 0], bits: 4 },      // multicast
  { base: [240, 0, 0, 0], bits: 4 },      // reservado + broadcast
];

function ipv4ToInt(o) {
  return ((o[0] << 24) >>> 0) + (o[1] << 16) + (o[2] << 8) + o[3];
}

function ipv4InRange(octets, range) {
  const mask = range.bits === 0 ? 0 : (0xffffffff << (32 - range.bits)) >>> 0;
  return ((ipv4ToInt(octets) & mask) >>> 0) === ((ipv4ToInt(range.base) & mask) >>> 0);
}

function isPublicIPv4(value) {
  const o = parseIPv4(value);
  if (!o) return false;
  return !IPV4_SPECIAL.some((r) => ipv4InRange(o, r));
}

// ---------------------------------------------------------------------------
// IPv6
// ---------------------------------------------------------------------------
function parseIPv6(value) {
  if (typeof value !== 'string' || value.length > 45) return null;
  let v = value.trim().toLowerCase();
  if (v.includes('%')) return null; // zone id não é aceito
  const lastColon = v.lastIndexOf(':');
  if (lastColon !== -1 && v.slice(lastColon + 1).includes('.')) {
    // IPv4 embutido no fim (ex.: ::ffff:a.b.c.d) vira dois grupos hexadecimais
    const v4 = parseIPv4(v.slice(lastColon + 1));
    if (!v4) return null;
    const hi = ((v4[0] << 8) | v4[1]).toString(16);
    const lo = ((v4[2] << 8) | v4[3]).toString(16);
    v = v.slice(0, lastColon + 1) + hi + ':' + lo;
  }
  const doubleColon = v.split('::');
  if (doubleColon.length > 2) return null;
  const toGroups = (s) => (s === '' ? [] : s.split(':'));
  const head = toGroups(doubleColon[0]);
  const rest = doubleColon.length === 2 ? toGroups(doubleColon[1]) : [];
  const hexOk = (g) => /^[0-9a-f]{1,4}$/.test(g);
  if (!head.every(hexOk) || !rest.every(hexOk)) return null;
  const explicit = head.length + rest.length;
  let groups;
  if (doubleColon.length === 2) {
    if (explicit > 7) return null;
    groups = [...head, ...Array(8 - explicit).fill('0'), ...rest].map((g) => parseInt(g, 16));
  } else {
    if (explicit !== 8) return null;
    groups = [...head, ...rest].map((g) => parseInt(g, 16));
  }
  return groups.length === 8 ? groups : null;
}

function formatIPv6(groups) {
  // RFC 5952: minúsculas, sem zeros à esquerda, comprime a maior sequência (>=2) de zeros
  let bestStart = -1;
  let bestLen = 0;
  for (let i = 0; i < 8; ) {
    if (groups[i] !== 0) { i++; continue; }
    let j = i;
    while (j < 8 && groups[j] === 0) j++;
    if (j - i > bestLen && j - i >= 2) { bestStart = i; bestLen = j - i; }
    i = j;
  }
  const hex = groups.map((g) => g.toString(16));
  if (bestStart === -1) return hex.join(':');
  const left = hex.slice(0, bestStart).join(':');
  const right = hex.slice(bestStart + bestLen).join(':');
  return left + '::' + right;
}

const IPV6_SPECIAL = [
  ['2001::', 23],      // IETF protocol assignments (inclui Teredo)
  ['2001:db8::', 32],  // documentação
  ['2002::', 16],      // 6to4
].map(([p, bits]) => ({ groups: parseIPv6(p), bits }));

function ipv6InPrefix(groups, prefix) {
  let bits = prefix.bits;
  for (let i = 0; i < 8 && bits > 0; i++) {
    const take = Math.min(16, bits);
    const mask = (0xffff << (16 - take)) & 0xffff;
    if ((groups[i] & mask) !== (prefix.groups[i] & mask)) return false;
    bits -= take;
  }
  return true;
}

function isPublicIPv6(value) {
  const g = parseIPv6(value);
  if (!g) return false;
  // somente unicast global (2000::/3), menos as faixas especiais acima
  if ((g[0] & 0xe000) !== 0x2000) return false;
  return !IPV6_SPECIAL.some((p) => ipv6InPrefix(g, p));
}

/**
 * Normaliza e valida um IP para desbloqueio. Retorna a forma canônica ou null.
 * Só aceita endereços públicos: desbloquear faixa privada/reservada não faz
 * sentido operacional e costuma ser sinal de erro ou abuso.
 */
function normalizePublicIp(value) {
  if (typeof value !== 'string') return null;
  const v = value.trim();
  if (v.includes(':')) {
    const g = parseIPv6(v);
    if (!g || !isPublicIPv6(v)) return null;
    return { version: 6, address: formatIPv6(g) };
  }
  if (!isPublicIPv4(v)) return null;
  return { version: 4, address: v };
}

// ---- src/text.js ----
// Extração de texto do card (Atlassian Document Format) e leitura de campos
// estruturados no formato "Chave: valor", um por linha.

const MAX_TEXT_LENGTH = 20000;

function adfToText(node) {
  if (node == null) return '';
  if (typeof node === 'string') return node.slice(0, MAX_TEXT_LENGTH);
  const out = [];
  const walk = (n) => {
    if (!n || typeof n !== 'object') return;
    if (n.type === 'text' && typeof n.text === 'string') out.push(n.text);
    if (n.type === 'hardBreak') out.push('\n');
    if (Array.isArray(n.content)) n.content.forEach(walk);
    if (['paragraph', 'heading', 'listItem', 'codeBlock', 'blockquote'].includes(n.type)) out.push('\n');
  };
  walk(node);
  return out.join('').replace(/\n{3,}/g, '\n\n').trim().slice(0, MAX_TEXT_LENGTH);
}

function normalizeKey(value) {
  return String(value)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

// Nome canônico do campo -> variações aceitas no template do card
const FIELD_ALIASES = {
  cliente: ['cliente', 'contacpanel', 'usuariocpanel', 'usuario'],
  ip: ['ip', 'enderecoip', 'ipbloqueado'],
  email: ['email', 'contadeemail', 'caixapostal', 'conta'],
  atividade: ['atividade', 'tipo', 'tipodeatividade'],
  periodo: ['periodo'],
};

const ALIAS_TO_FIELD = Object.entries(FIELD_ALIASES).reduce((acc, [field, aliases]) => {
  aliases.forEach((a) => { acc[a] = field; });
  return acc;
}, {});

/**
 * Lê linhas "Chave: valor". Só campos conhecidos são considerados; um campo
 * repetido com valores diferentes é marcado como ambíguo (o card é recusado).
 */
function parseFields(text) {
  const fields = {};
  const ambiguous = new Set();
  String(text || '').split(/\r?\n/).forEach((line) => {
    const m = line.match(/^\s*[-*]?\s*([^:]{1,40}):\s*(.{1,320}?)\s*$/);
    if (!m) return;
    const field = ALIAS_TO_FIELD[normalizeKey(m[1])];
    if (!field) return;
    const value = m[2].trim();
    if (fields[field] !== undefined && fields[field] !== value) ambiguous.add(field);
    else fields[field] = value;
  });
  return { fields, ambiguous: [...ambiguous] };
}

function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

// ---- src/inventory.js ----
// Inventório: fonte da verdade sobre quais contas existem, em qual servidor
// estão, quais domínios pertencem a cada conta e quem é o contato responsável.
// O texto do card nunca decide servidor nem dono de domínio: só o inventário.



const SERVER_NAME_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;

function parseInventory(raw) {
  let inv = raw;
  if (typeof raw === 'string') {
    try { inv = JSON.parse(raw); } catch (e) { throw new Error('inventory: JSON inválido'); }
  }
  if (!inv || typeof inv !== 'object') throw new Error('inventory: objeto ausente');
  const servers = inv.servers || {};
  const accounts = inv.accounts || {};
  for (const [name, srv] of Object.entries(servers)) {
    if (!SERVER_NAME_RE.test(name)) throw new Error('inventory: nome de servidor inválido');
    if (!srv || !isValidHostname(srv.host)) throw new Error('inventory: host inválido em ' + name);
  }
  const aliasIndex = new Map();
  for (const [user, acc] of Object.entries(accounts)) {
    if (!isValidCpanelUser(user)) throw new Error('inventory: usuário cPanel inválido');
    if (!acc || !servers[acc.server]) throw new Error('inventory: servidor desconhecido para ' + user);
    if (!Array.isArray(acc.domains) || !acc.domains.every(isValidHostname)) {
      throw new Error('inventory: domínios inválidos para ' + user);
    }
    if (acc.contact !== undefined && !parseEmail(acc.contact)) {
      throw new Error('inventory: contato inválido para ' + user);
    }
    for (const alias of [user, ...(acc.aliases || [])]) {
      const k = normalizeKey(alias);
      if (!k) continue;
      if (!aliasIndex.has(k)) aliasIndex.set(k, new Set());
      aliasIndex.get(k).add(user);
    }
  }
  return { servers, accounts, aliasIndex };
}

/**
 * Resolve o campo "Cliente" do card para uma conta do inventário.
 * Correspondência exata (usuário ou alias normalizado). Sem busca por
 * substring: "ana" nunca deve casar com "mariana".
 */
function resolveAccount(inventory, value) {
  const k = normalizeKey(value || '');
  if (!k) return { status: 'missing' };
  const users = inventory.aliasIndex.get(k);
  if (!users || users.size === 0) return { status: 'not_found' };
  if (users.size > 1) return { status: 'ambiguous' };
  const user = [...users][0];
  const account = inventory.accounts[user];
  return { status: 'ok', user, account, server: account.server, host: inventory.servers[account.server].host };
}

function accountOwnsDomain(account, domain) {
  return Array.isArray(account.domains) && account.domains.includes(domain);
}

/** Domínio (ou subdomínio) -> conta dona, pelo sufixo mais longo em fronteira de rótulo. */
function findAccountByHostname(inventory, hostname) {
  let best = null;
  for (const [user, acc] of Object.entries(inventory.accounts)) {
    for (const d of acc.domains) {
      if (hostname === d || hostname.endsWith('.' + d)) {
        if (!best || d.length > best.domain.length) best = { user, domain: d, server: acc.server };
      }
    }
  }
  if (!best) return null;
  return { ...best, host: inventory.servers[best.server].host };
}

// ---- src/config.js ----
// Configuração lida de variáveis de ambiente do n8n ($env).
// Só configuração vai aqui; segredos ficam no cofre de credenciais do n8n.
// Padrões seguros: dry-run ligado, allowlist vazia, aprovação obrigatória.


function parseBool(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  return /^(1|true|yes|sim|on)$/i.test(String(value).trim());
}

function parseIntInRange(value, fallback, min, max) {
  const n = Number.parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function parseList(value) {
  return String(value || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

const SSH_MODES = ['forced-command', 'sudo-wrapper'];

function readConfig(env) {
  const e = env || {};
  const sshMode = SSH_MODES.includes(e.OPS_SSH_MODE) ? e.OPS_SSH_MODE : 'forced-command';
  return {
    jiraBaseUrl: String(e.JIRA_BASE_URL || 'https://example.atlassian.net').replace(/\/+$/, ''),
    projectKeys: parseList(e.JIRA_PROJECT_KEYS || 'OPS'),
    automationStatus: e.JIRA_AUTOMATION_STATUS || 'Selecionado para Automação',
    statusDone: e.JIRA_STATUS_DONE || 'Conferir e Avisar',
    statusTriage: e.JIRA_STATUS_TRIAGE || 'Triagem Manual',
    claimLabel: e.JIRA_CLAIM_LABEL || 'ops-automation-claimed',
    botAccountId: e.JIRA_BOT_ACCOUNT_ID || '',
    approverIds: parseList(e.OPS_APPROVER_ACCOUNT_IDS),
    requireFourEyes: parseBool(e.OPS_REQUIRE_FOUR_EYES, true),
    dryRun: parseBool(e.OPS_DRY_RUN, true),
    allowedActivities: parseList(e.OPS_ALLOWED_ACTIVITIES),
    maxActionsPerRun: parseIntInRange(e.OPS_MAX_ACTIONS_PER_RUN, 5, 0, 50),
    searchMaxResults: parseIntInRange(e.JIRA_SEARCH_MAX_RESULTS, 25, 1, 100),
    sshMode,
    passwordLength: parseIntInRange(e.OPS_PASSWORD_LENGTH, 20, 16, 64),
    secretTtlHours: parseIntInRange(e.OPS_SECRET_TTL_HOURS, 24, 1, 72),
    sslMaxRetries: parseIntInRange(e.SSL_MAX_RETRIES, 1, 0, 3),
    sslDedupHours: parseIntInRange(e.SSL_DEDUP_HOURS, 12, 0, 168),
    inventory: parseInventory(e.OPS_INVENTORY_JSON || '{"servers":{},"accounts":{}}'),
  };
}

// ---- src/audit.js ----
// Evento de auditoria: o que foi decidido, por quê, com quais argumentos
// validados e por quem foi aprovado. Nunca carrega segredo.

const FORBIDDEN_KEY_RE = /pass(word)?|senha|secret|token|authorization|cookie/i;

function assertNoSecretFields(obj, path) {
  if (!obj || typeof obj !== 'object') return;
  for (const [k, v] of Object.entries(obj)) {
    if (FORBIDDEN_KEY_RE.test(k)) throw new Error('audit: campo sensível em ' + (path ? path + '.' : '') + k);
    assertNoSecretFields(v, (path ? path + '.' : '') + k);
  }
}

function buildAuditEvent(input) {
  const i = input || {};
  const plan = i.plan || null;
  const event = {
    schema: 'ops-automation.audit.v1',
    at: i.now || new Date().toISOString(),
    executionId: i.executionId || null,
    workflow: i.workflow || 'infra',
    issueKey: i.issueKey || null,
    activity: i.activity || null,
    decision: i.route || null,
    reason: i.reason || null,
    dryRun: Boolean(i.dryRun),
    approver: i.approver || null,
    outcome: i.outcome || null,
    target: plan ? { server: plan.server, executor: plan.executor, command: plan.commandId || null, args: plan.args || [] } : null,
  };
  assertNoSecretFields(event);
  return event;
}

// ---- src/result.js ----
// Interpretação do retorno das execuções e montagem do comentário final.
// O comentário nunca inclui stderr bruto, saída de comando nem segredo.


const ERROR_CODE_RE = /^[a-z][a-z0-9_]{0,40}$/;

/**
 * O wrapper do servidor imprime uma única linha JSON no fim da saída.
 * Aceita a saída do nó SSH ({ stdout, stderr, code }) ou um erro do nó.
 */
function parseCatalogOutput(sshOutput) {
  const o = sshOutput || {};
  if (o.error && !o.stdout) return { ok: false, error: 'ssh_failed' };
  const lines = String(o.stdout || '').trim().split('\n').reverse();
  for (const line of lines) {
    const t = line.trim();
    if (!t.startsWith('{')) continue;
    try {
      const data = JSON.parse(t);
      if (typeof data.ok !== 'boolean') continue;
      const error = data.ok ? null : (ERROR_CODE_RE.test(String(data.error)) ? data.error : 'unknown_error');
      return { ok: data.ok, error, data };
    } catch (e) {
      // linha que parece JSON mas não é: continua procurando
    }
  }
  return { ok: false, error: 'no_result_line' };
}

/** Resposta de WHM json-api/uapi_cpanel: sucesso só se as duas camadas confirmarem. */
function whmUapiSucceeded(resp) {
  const r = resp || {};
  if (r.error) return false;
  const metaOk = r.metadata && Number(r.metadata.result) === 1;
  const uapiOk = r.data && r.data.uapi && Number(r.data.uapi.status) === 1;
  return Boolean(metaOk && uapiOk);
}

function safeInt(v) {
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 && n < 10_000_000 ? Math.round(n) : null;
}

function successComment(ctx, parsed) {
  const plan = ctx.plan;
  if (ctx.activity === 'ip_unblock') {
    return [
      'Automação: IP desbloqueado.',
      'IP: ' + plan.args[0],
      'Servidor: ' + plan.server,
      'O IP foi removido das listas de bloqueio do firewall. Nenhuma liberação permanente foi criada.',
    ].join('\n');
  }
  if (ctx.activity === 'mail_quota_increase') {
    const before = safeInt(parsed.data && parsed.data.before_mb);
    const after = safeInt(parsed.data && parsed.data.new_mb);
    return [
      'Automação: cota de e-mail ajustada.',
      'Conta: ' + plan.args[1] + '@' + plan.args[2],
      'Cota anterior: ' + (before === null ? 'n/d' : before + ' MB'),
      'Cota nova: ' + (after === null ? 'n/d' : after + ' MB'),
    ].join('\n');
  }
  if (ctx.activity === 'mail_password_reset') {
    return [
      'Automação: senha de e-mail redefinida.',
      'Conta: ' + plan.mailbox,
      'A nova senha foi enviada ao contato responsável cadastrado, por link de uso único com validade limitada.',
      'A senha não é registrada neste card nem no histórico da automação.',
    ].join('\n');
  }
  return 'Automação: atividade concluída.';
}

function failureComment(ctx, code) {
  const lines = ['Automação: a execução não foi concluída.', 'Código: ' + code];
  if (code === 'secret_delivery_failed') {
    lines.push('A senha foi redefinida, mas o link de entrega não foi gerado. Siga o runbook: redefinir de novo pelo procedimento manual.');
  }
  lines.push('O card foi encaminhado para triagem manual.');
  return lines.join('\n');
}

/**
 * ctx: item do planejador. input: saída do nó anterior.
 * - ssh: { stdout, stderr, code } do nó SSH
 * - whm: { applied, delivered } dos nós "Avaliar ..."
 */
function interpretResult(ctx, input, cfg) {
  let ok;
  let code = null;
  let parsed = { data: {} };
  if (ctx.plan.executor === 'ssh') {
    parsed = parseCatalogOutput(input);
    ok = parsed.ok;
    code = parsed.error;
  } else {
    const i = input || {};
    ok = Boolean(i.applied && i.delivered);
    code = ok ? null : (i.applied ? 'secret_delivery_failed' : 'whm_call_failed');
  }
  const outcome = ok ? 'success' : 'failure';
  return {
    issueKey: ctx.issueKey,
    outcome,
    jiraComment: ok ? successComment(ctx, parsed) : failureComment(ctx, code),
    targetStatus: ok ? cfg.statusDone : cfg.statusTriage,
    audit: buildAuditEvent({
      ...ctx.audit,
      issueKey: ctx.issueKey,
      activity: ctx.activity,
      route: 'execute',
      reason: code,
      outcome,
      approver: ctx.approver,
      plan: ctx.plan,
      now: new Date().toISOString(),
      executionId: ctx.audit && ctx.audit.executionId,
    }),
  };
}

